ublic.anweshan_amazon_ads_campaign_details cd ON o.campaign_id = cd.campaignid LEFT JOIN public.anweshan_amazon_ads_adgroup_details adg ON o.campaign_id = adg.campaignid AND o.AD_GROUP_ID = adg.adgroupid LEFT JOIN public.anweshan_amazon_ads_ad_details add ON o.campaign_id = add.campaignid AND o.AD_GROUP_ID = add.adgroupid AND o.ad_id = add.adid LEFT JOIN public.anweshan_amazon_ads_targeting_details td ON o.campaign_id = td.campaignid AND o.AD_GROUP_ID = td.adgroupid AND o.target_id = td.targetid LEFT JOIN public.anweshan_amazon_ads_keyword_details kd ON o.campaign_id = kd.campaignid AND o.AD_GROUP_ID = kd.adgroupid AND o.keyword_id = kd.keywordid LEFT JOIN public.anweshan_amazon_ads_profile_details pd ON CAST(o.profileid AS VARCHAR) = CAST(pd.profileid AS VARCHAR);",
